// Авторские предыстории Эноа по правилам D&D 2024.
//
// Целевой каркас редакции 2024 (унаследованное исключение Free отмечено отдельно):
//   • три характеристики (+2/+1 на две из них или +1/+1/+1 на все три);
//   • одна черта происхождения;
//   • владение двумя навыками;
//   • владение одним инструментом;
//   • снаряжение: набор «А» либо 50 зм.
//
// Всё, что делает предысторию частью Эноа, вынесено в поля `enoaLead`, `variants` и `hooks`:
// Авторские записи могут иметь собственные механики; источник и статус указаны у черты. Каталог использует правила 2024
// и не смешивается с материалами редакции 2014 года.
//
// Поле `glossary` — ручные ссылки на ширму /dnd55e/glossary: термины, которые стоит
// прочитать до первой сессии именно за этого персонажа. Ссылки на характеристики,
// навыки, инструмент и снаряжение собираются автоматически по таблицам ниже.

