        "title": "Искавший Пылающие Пески",
        "region": "Пески юга",
        "text": "Вы шли к Школе Пылающих Песков по слухам, следам костров и словам пастухов. Дважды вы находили стоянку, покинутую за неделю до вас, и оба раза угли казались тёплыми."
