    "play": "Выживание помогает выбрать путь и стоянку, Убеждение — договориться об условиях прохода. «Одарённый» даёт три владения навыками или инструментами в дополнение к двум навыкам предыстории. Знакомство с дорогой не означает автоматического знакомства со всеми её жителями."
