    "play": "Анализ и Убеждение — следовательский и торговый профиль сразу, а «Везунчик» страхует решающий бросок в переговорах. Инструменты ювелира определяют стоимость камней, что напрямую влияет на добычу партии: с оценщиком отряд перестаёт продавать находки вслепую. Хорош для барда, плута и любого персонажа, ведущего дела отряда."
