    "play": "Обман помогает скрывать замысел, Ловкость рук — обращаться с находками и тайниками. Игровой набор отражает опыт состязаний, а «Везунчик» предоставляет ограниченное влияние на броски по условиям черты. Ни удача, ни происхождение не гарантируют победы или желаемого сюжетного исхода."
