    "play": "«Ремесленник» здесь работает как исследовательская черта: три инструмента и скидка на всё немагическое — то, чем живёт экспедиция. Аркана со Скрытностью — редкая пара «понять и не разбудить», и она делает персонажа первым, кто входит в руины. Хорош для волшебника, изобретателя и плута-археолога."
