    "play": "Зеркало Нагбо: та же земля, обратная сторона Вирмоханы. Атлетика с Религией — тело и обряд, то, чем норбу и меряют, а «Крепкий» отыгрывает идеальный Кремень прибавкой хитов. Инструменты кузнеца чинят оружие и доспехи в поле. Хорош для паладина, воина и монаха; в паре с Нагбо за одним столом даёт готовый внутренний конфликт без единой механической привилегии у одной из сторон.",
