    "play": "Религия помогает понимать обряд, Природа — сопоставлять приметы с окружающей средой. «Крепкий» отражает выдержку, приобретённую в испытаниях. Игровой набор в комплекте — обычные кости; оформление как шагай не выдаёт дополнительных механик знамений автоматически."
