    "play": "Аркана помогает оценить магические признаки, Внимательность — заметить угрозу. «Бдительный» улучшает инициативу и позволяет обменяться ею по правилам черты, но не гарантирует первого хода. Инструменты кузнеца применяются к ремонту с обычными требованиями к времени и материалам."
