    "play": "Анализ с Проницательностью — чистый следовательский профиль: улика и человек за ней. «Везунчик» страхует тот единственный бросок, на котором держится прикрытие. Набор для фальсификации закрывает отметки и манеру плетения. Хорош для плута, барда-дознавателя и любого персонажа, ведущего расследование внутри организации."
