    "play": "Атлетика с Уходом за животными — взять степь телом и не потерять коня. «Крепкий» отыгрывает пережитое испытание прибавкой хитов. Титул даёт уважение кочевников, но не власть: племени у персонажа нет, и заслужить его — готовая долгая цель на всю кампанию. Хорош для варвара, следопыта и паладина; Харизма в тройке — задел на тот день, когда за тигром пойдут."
