    "enoaLead": [
      "Переправа через М’лах связывает путника с островами Братства Глубин. Невыплаченный долг там понимают как обет, а не просто сумму солнц; он может превратиться в поручение далеко от берега. Запись обязательства хранит, кто и за что отвечает, но не сообщает заранее, когда попросят исполнения. Должник учится узнавать посредников и беречь условия передачи, потому что от точности небольшого дела зависит продолжение большого долга.",
      "Пока долг связывал вас с островами озера М’лах, вы выполняли поручения: переносили свёртки, встречали людей и следили, чтобы передача прошла без лишнего шума. В тесноте пристаней приходилось быстро работать руками, удерживаться на ногах и разбираться в чужих намерениях. Игры с лодочниками учили выдержке, а дорожные стычки — защищаться тем, что оказалось рядом. Так вы приобрели ловкость и привычку терпеть неудобства."
    ],
