    "play": "Ловкость рук с Проницательностью — единственная такая пара каталога: быстрые пальцы и чтение людей, то есть готовый плут без класса плута. «Драчун» отыгрывает то, чем долги отдают чаще всего. Долг перед культом даёт мастеру рычаг на всю кампанию и не стоит партии ни одного очка механики: братство не враг и не покровитель, оно просто помнит. Хорош для плута, монаха и барда."
