    "play": "Анализ со Скрытностью — «выяснить и не попасться», связка следователя под прикрытием, которой в каталоге не было. «Одарённый» добавляет три владения навыками или инструментами: тот, за кем охотятся, обязан уметь многое. Набор для фальсификации закрывает отметки, манеру плетения и чужие имена. Мастеру: это готовая пружина городской кампании — знание опасно само по себе, без единого броска, и одинаково нужно обеим сторонам. Хорош для плута, барда и волшебника."
