    "play": "Предыстория только для худдулинов разновидности «омор». Черта «Камень обо» после каждого отдыха даёт вам и союзникам немного временных хитов, а в степи и пустошах помогает найти воду, пищу и укрытие. Акробатика и Религия — для того, кто хранил святыню и уходил от тех, кто её разорял. Хорош для жреца, друида и монаха."
