    "play": "Черта «Тропы Шаха Дюн» раз в день отмечает добычу: +1к4 урона оружием по ней и преимущество, чтобы её выследить. Песок вас не замедляет, жара и холод не берут, а в пути вы не заблудитесь без магии. Внимательность и Выживание делают из вас проводника и следопыта. Хорош для следопыта, воина и плута."
