    "play": "Черта «Возлюбленный Всадницы» связывает вас со скакуном: верхом он делает спасброски с вашим бонусом, а раз за короткий отдых вы добавляете 1к6 к тесту к20 — своему или скакуна. Звери чуют в вас частицу Бат’рины: Уход за животными с преимуществом. Хорош для следопыта, паладина и воина, особенно если в партии есть аюр. Не путать с Великими гонками удришей и со «Степным тигром»."
