    "play": "Существующая версия предоставляет свободную черту «Проклятье Айруна» вместо Origin и требует отдельного соглашения для стандартной игры 2024. Уход за животными и Запугивание описывают отношения с миром, а превращение регулируется отдельным текстом черты. Связанные «Пробуждённый зверь» и «Дар любимца» сохранены; сюжетные последствия согласуйте заранее, не назначая персонажу обязательный путь развития."
