    "play": "Черта «Собутыльник Чидкура» — трикстерская: преимущество против отравления, пьянеете вы только по желанию, раз за короткий отдых Реакцией сбиваете чужую атаку выходкой, а крысы не трогают вас первыми. Природа и Убеждение — дорога и умение договориться у любого огня. Хорош для барда, плута и воина. Тон мрачно-комический. Чидкур ненавидит Сальбара и рузд — готовый конфликт с «Учеником Рузды»."
