    "play": "Черта «Глаза ковена» — для расследования: минута наблюдения подсказывает, колдует ли существо и не Исчадие ли оно, Небожитель, Фея или Нежить; час расспросов приносит слух; страх берёт вас с трудом — страшнее хозяина никого нет. Анализ и Религия — поиск того, что ищет ковен. Хорош для плута, колдуна и барда. Зеркало «Соглядатая Белых Соколов»: там служба людям, здесь — существу из тени, и цена ошибки — жизнь."
