    "play": "Черта «Память Спирали»: браслет из сальбария становится простым оружием ближнего боя или инструментом и возвращается на запястье, если его отнять; раз за короткий отдых он растекается щитом (+2 к КД против одной атаки); ещё один инструмент ремесленника на выбор. История и Ловкость рук — память о прошлом и руки, которые его помнят. Подходит любому народу, особенно мор’хорам. Хорош для изобретателя, плута и воина. Сыграйте чужака во времени: этот мир для вас новый."
